-- Dun Morogh, Coldridge Valley and New Tinkertown: creature abilities
-- Most of the Cataclysm-era creatures (Frostmane, Rockjaw, Crushcog, Dark Iron, Wendigos, the Kharanos and Amberstill dwarves) had
-- no AI and only melee'd, and several older ones ran classic rows. Port their abilities from the Cataclysm data, and from the
-- classic data where Cataclysm has none (Winter Wolf). Quest and event scripts already in place are kept.

SET @ENTRIES := '708,808,1115,1119,1131,1260,1679,1961,6123,6124,8503,13076,37073,37081,37105,37112,37115,37507,40940,40941,41121,41122,41146,41175,41181,41182,41251,41258,41284,41478,41544,41611,41761,41762,41897,41898,41902,41909,41924,42003,42010,42170,42184,42221,42222,42223,42226,42286,42290,42291,42773,42894,43230,43325,51912';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
